00045 #pragma once
00046 #ifndef AI_VECTOR3D_INL_INC
00047 #define AI_VECTOR3D_INL_INC
00048 
00049 #ifdef __cplusplus
00050 #include <assimp/vector3.h>
00051 
00052 #include <cmath>
00053 
00054 // ------------------------------------------------------------------------------------------------
00056 template <typename TReal>
00057 AI_FORCE_INLINE aiVector3t<TReal> operator * (const aiMatrix3x3t<TReal>& pMatrix, const aiVector3t<TReal>& pVector) {
00058     aiVector3t<TReal> res;
00059     res.x = pMatrix.a1 * pVector.x + pMatrix.a2 * pVector.y + pMatrix.a3 * pVector.z;
00060     res.y = pMatrix.b1 * pVector.x + pMatrix.b2 * pVector.y + pMatrix.b3 * pVector.z;
00061     res.z = pMatrix.c1 * pVector.x + pMatrix.c2 * pVector.y + pMatrix.c3 * pVector.z;
00062     return res;
00063 }
00064 
00065 // ------------------------------------------------------------------------------------------------
00067 template <typename TReal>
00068 AI_FORCE_INLINE aiVector3t<TReal> operator * (const aiMatrix4x4t<TReal>& pMatrix, const aiVector3t<TReal>& pVector) {
00069     aiVector3t<TReal> res;
00070     res.x = pMatrix.a1 * pVector.x + pMatrix.a2 * pVector.y + pMatrix.a3 * pVector.z + pMatrix.a4;
00071     res.y = pMatrix.b1 * pVector.x + pMatrix.b2 * pVector.y + pMatrix.b3 * pVector.z + pMatrix.b4;
00072     res.z = pMatrix.c1 * pVector.x + pMatrix.c2 * pVector.y + pMatrix.c3 * pVector.z + pMatrix.c4;
00073     return res;
00074 }
00075 // ------------------------------------------------------------------------------------------------
00076 template <typename TReal>
00077 template <typename TOther>
00078 aiVector3t<TReal>::operator aiVector3t<TOther> () const {
00079     return aiVector3t<TOther>(static_cast<TOther>(x),static_cast<TOther>(y),static_cast<TOther>(z));
00080 }
00081 // ------------------------------------------------------------------------------------------------
00082 template <typename TReal>
00083 AI_FORCE_INLINE void aiVector3t<TReal>::Set( TReal pX, TReal pY, TReal pZ) {
00084     x = pX;
00085     y = pY;
00086     z = pZ;
00087 }
00088 // ------------------------------------------------------------------------------------------------
00089 template <typename TReal>
00090 AI_FORCE_INLINE TReal aiVector3t<TReal>::SquareLength() const {
00091     return x*x + y*y + z*z;
00092 }
00093 // ------------------------------------------------------------------------------------------------
00094 template <typename TReal>
00095 AI_FORCE_INLINE TReal aiVector3t<TReal>::Length() const {
00096     return std::sqrt( SquareLength());
00097 }
00098 // ------------------------------------------------------------------------------------------------
00099 template <typename TReal>
00100  aiVector3t<TReal>& aiVector3t<TReal>::Normalize() {
00101     const TReal l = Length();
00102     if (l == 0) {
00103         return *this;
00104     }
00105     *this /= Length();
00106 
00107     return *this;
00108 }
00109 // ------------------------------------------------------------------------------------------------
00110 template <typename TReal>
00111 AI_FORCE_INLINE aiVector3t<TReal>& aiVector3t<TReal>::NormalizeSafe() {
00112     TReal len = Length();
00113     if ( len > static_cast< TReal >( 0 ) ) {
00114         *this /= len;
00115     }
00116     return *this;
00117 }
00118 // ------------------------------------------------------------------------------------------------
00119 template <typename TReal>
00120 AI_FORCE_INLINE const aiVector3t<TReal>& aiVector3t<TReal>::operator += (const aiVector3t<TReal>& o) {
00121     x += o.x;
00122     y += o.y;
00123     z += o.z;
00124 
00125     return *this;
00126 }
00127 // ------------------------------------------------------------------------------------------------
00128 template <typename TReal>
00129 AI_FORCE_INLINE const aiVector3t<TReal>& aiVector3t<TReal>::operator -= (const aiVector3t<TReal>& o) {
00130     x -= o.x;
00131     y -= o.y;
00132     z -= o.z;
00133 
00134     return *this;
00135 }
00136 // ------------------------------------------------------------------------------------------------
00137 template <typename TReal>
00138 AI_FORCE_INLINE const aiVector3t<TReal>& aiVector3t<TReal>::operator *= (TReal f) {
00139     x *= f;
00140     y *= f;
00141     z *= f;
00142 
00143     return *this;
00144 }
00145 // ------------------------------------------------------------------------------------------------
00146 template <typename TReal>
00147 AI_FORCE_INLINE const aiVector3t<TReal>& aiVector3t<TReal>::operator /= (TReal f) {
00148     if ( f == static_cast<TReal>(0.0)) {
00149         return *this;
00150     }
00151     const TReal invF = (TReal) 1.0 / f;
00152     x *= invF;
00153     y *= invF;
00154     z *= invF;
00155 
00156     return *this;
00157 }
00158 // ------------------------------------------------------------------------------------------------
00159 template <typename TReal>
00160 AI_FORCE_INLINE aiVector3t<TReal>& aiVector3t<TReal>::operator *= (const aiMatrix3x3t<TReal>& mat){
00161     return (*this =  mat * (*this));
00162 }
00163 // ------------------------------------------------------------------------------------------------
00164 template <typename TReal>
00165 AI_FORCE_INLINE aiVector3t<TReal>& aiVector3t<TReal>::operator *= (const aiMatrix4x4t<TReal>& mat){
00166     return (*this = mat * (*this));
00167 }
00168 // ------------------------------------------------------------------------------------------------
00169 template <typename TReal>
00170 AI_FORCE_INLINE TReal aiVector3t<TReal>::operator[](unsigned int i) const {
00171     switch (i) {
00172         case 0:
00173             return x;
00174         case 1:
00175             return y;
00176         case 2:
00177             return z;
00178         default:
00179             break;
00180     }
00181     return x;
00182 }
00183 // ------------------------------------------------------------------------------------------------
00184 template <typename TReal>
00185 AI_FORCE_INLINE TReal& aiVector3t<TReal>::operator[](unsigned int i) {
00186     switch (i) {
00187         case 0:
00188             return x;
00189         case 1:
00190             return y;
00191         case 2:
00192             return z;
00193         default:
00194             break;
00195     }
00196     return x;
00197 }
00198 // ------------------------------------------------------------------------------------------------
00199 template <typename TReal>
00200 AI_FORCE_INLINE bool aiVector3t<TReal>::operator== (const aiVector3t<TReal>& other) const {
00201     return x == other.x && y == other.y && z == other.z;
00202 }
00203 // ------------------------------------------------------------------------------------------------
00204 template <typename TReal>
00205 AI_FORCE_INLINE bool aiVector3t<TReal>::operator!= (const aiVector3t<TReal>& other) const {
00206     return x != other.x || y != other.y || z != other.z;
00207 }
00208 // ---------------------------------------------------------------------------
00209 template<typename TReal>
00210 AI_FORCE_INLINE bool aiVector3t<TReal>::Equal(const aiVector3t<TReal>& other, TReal epsilon) const {
00211     return
00212         std::abs(x - other.x) <= epsilon &&
00213         std::abs(y - other.y) <= epsilon &&
00214         std::abs(z - other.z) <= epsilon;
00215 }
00216 // ------------------------------------------------------------------------------------------------
00217 template <typename TReal>
00218 AI_FORCE_INLINE bool aiVector3t<TReal>::operator < (const aiVector3t<TReal>& other) const {
00219     return x != other.x ? x < other.x : y != other.y ? y < other.y : z < other.z;
00220 }
00221 // ------------------------------------------------------------------------------------------------
00222 template <typename TReal>
00223 AI_FORCE_INLINE const aiVector3t<TReal> aiVector3t<TReal>::SymMul(const aiVector3t<TReal>& o) {
00224     return aiVector3t<TReal>(x*o.x,y*o.y,z*o.z);
00225 }
00226 // ------------------------------------------------------------------------------------------------
00227 // symmetric addition
00228 template <typename TReal>
00229 AI_FORCE_INLINE aiVector3t<TReal> operator + (const aiVector3t<TReal>& v1, const aiVector3t<TReal>& v2) {
00230     return aiVector3t<TReal>( v1.x + v2.x, v1.y + v2.y, v1.z + v2.z);
00231 }
00232 // ------------------------------------------------------------------------------------------------
00233 // symmetric subtraction
00234 template <typename TReal>
00235 AI_FORCE_INLINE aiVector3t<TReal> operator - (const aiVector3t<TReal>& v1, const aiVector3t<TReal>& v2) {
00236     return aiVector3t<TReal>( v1.x - v2.x, v1.y - v2.y, v1.z - v2.z);
00237 }
00238 // ------------------------------------------------------------------------------------------------
00239 // scalar product
00240 template <typename TReal>
00241 AI_FORCE_INLINE TReal operator * (const aiVector3t<TReal>& v1, const aiVector3t<TReal>& v2) {
00242     return v1.x*v2.x + v1.y*v2.y + v1.z*v2.z;
00243 }
00244 // ------------------------------------------------------------------------------------------------
00245 // scalar multiplication
00246 template <typename TReal>
00247 AI_FORCE_INLINE aiVector3t<TReal> operator * ( TReal f, const aiVector3t<TReal>& v) {
00248     return aiVector3t<TReal>( f*v.x, f*v.y, f*v.z);
00249 }
00250 // ------------------------------------------------------------------------------------------------
00251 // and the other way around
00252 template <typename TReal>
00253 AI_FORCE_INLINE aiVector3t<TReal> operator * ( const aiVector3t<TReal>& v, TReal f) {
00254     return aiVector3t<TReal>( f*v.x, f*v.y, f*v.z);
00255 }
00256 // ------------------------------------------------------------------------------------------------
00257 // scalar division
00258 template <typename TReal>
00259 AI_FORCE_INLINE aiVector3t<TReal> operator / ( const aiVector3t<TReal>& v, TReal f) {
00260     return v * (1/f);
00261 }
00262 // ------------------------------------------------------------------------------------------------
00263 // vector division
00264 template <typename TReal>
00265 AI_FORCE_INLINE aiVector3t<TReal> operator / ( const aiVector3t<TReal>& v, const aiVector3t<TReal>& v2) {
00266     return aiVector3t<TReal>(v.x / v2.x,v.y / v2.y,v.z / v2.z);
00267 }
00268 // ------------------------------------------------------------------------------------------------
00269 // cross product
00270 template<typename TReal>
00271 AI_FORCE_INLINE aiVector3t<TReal> operator ^ ( const aiVector3t<TReal>& v1, const aiVector3t<TReal>& v2) {
00272     return aiVector3t<TReal>( v1.y*v2.z - v1.z*v2.y, v1.z*v2.x - v1.x*v2.z, v1.x*v2.y - v1.y*v2.x);
00273 }
00274 // ------------------------------------------------------------------------------------------------
00275 // vector negation
00276 template<typename TReal>
00277 AI_FORCE_INLINE aiVector3t<TReal> operator - ( const aiVector3t<TReal>& v) {
00278     return aiVector3t<TReal>( -v.x, -v.y, -v.z);
00279 }
00280 
